public class CurrentThreadInfo {
    public static void main(String[] args) {
        Thread current = Thread.currentThread();
        System.out.println("Thread name: " + current.getName());
        System.out.println("Thread priority: " + current.getPriority());
    }
}

public class ThreadSettingsDemo {
    public static void main(String[] args) {
        Thread current = Thread.currentThread();
        System.out.println(current.getName() + " " + current.getPriority());
        current.setName("Application-Main");
        current.setPriority(8);
        System.out.println(current.getName() + " " + current.getPriority());
    }
}

public class SingleRunMethodDemo extends Thread {
    @Override
    public void run() {
        String task = Thread.currentThread().getName();
        if (task.equals("add"))
            System.out.println("Sum: " + (10 + 20));
        else if (task.equals("printing characters"))
            System.out.println("Characters: A B C D E");
        else if (task.equals("printing numbers"))
            System.out.println("Numbers: 1 2 3 4 5");
    }

    public static void main(String[] args) {
        SingleRunMethodDemo first = new SingleRunMethodDemo();
        SingleRunMethodDemo second = new SingleRunMethodDemo();
        SingleRunMethodDemo third = new SingleRunMethodDemo();
        first.setName("add");
        second.setName("printing characters");
        third.setName("printing numbers");
        first.start();
        second.start();
        third.start();
    }
}

